<script setup lang="ts">
const route = useRoute(); const token = computed(() => typeof route.query.token === 'string' ? route.query.token : '')
const password = ref(''); const confirmation = ref(''); const error = ref(''); const success = ref(false); const pending = ref(false)
onMounted(() => { const requested = route.query.lang; if (requested === 'ru' || requested === 'en' || requested === 'he') void setLocale(requested) })
const { t, setLocale } = useI18n()
async function submit() { error.value = ''; if (!token.value) { error.value = t('auth.invalidLink'); return } if (password.value !== confirmation.value) { error.value = t('auth.passwordMismatch'); return } pending.value = true; try { await $fetch('/api/auth/set-password', { method: 'POST', body: { token: token.value, password: password.value } }); success.value = true } catch (cause: any) { error.value = cause?.data?.statusMessage ?? t('auth.invalidPasswordSetup') } finally { pending.value = false } }
</script>
<template><div class="w-full max-w-md"><NuxtLink to="/login" class="brand-mark mb-10 text-2xl lg:hidden">aparts<span>.</span></NuxtLink><div class="surface p-6 sm:p-8"><template v-if="success"><div class="grid size-12 place-items-center rounded-2xl bg-[var(--color-primary-soft)] text-[var(--color-primary)]"><UIcon name="i-lucide-check" class="size-6" /></div><h2 class="mt-6 text-3xl font-semibold tracking-[-.045em]">{{ t('auth.passwordSet') }}</h2><p class="mt-2 text-sm leading-6 text-[var(--color-muted)]">{{ t('auth.accountReady') }}</p><UButton to="/login" block size="lg" class="mt-7">{{ t('auth.goToLogin') }}</UButton></template><template v-else><h2 class="text-3xl font-semibold tracking-[-.045em]">{{ t('auth.createPassword') }}</h2><p class="mt-2 text-sm leading-6 text-[var(--color-muted)]">{{ t('auth.passwordHint') }}</p><form class="mt-7 space-y-5" @submit.prevent="submit"><UFormField :label="t('auth.newPassword')"><UInput v-model="password" type="password" autocomplete="new-password" class="w-full" minlength="8" required /></UFormField><UFormField :label="t('auth.repeatPassword')"><UInput v-model="confirmation" type="password" autocomplete="new-password" class="w-full" minlength="8" required /></UFormField><UAlert v-if="error" color="error" variant="soft" :description="error" /><UButton type="submit" block size="lg" :loading="pending">{{ t('auth.savePassword') }}</UButton></form></template></div></div></template>
